# Problem 123: Fill zeros to make sequence non-increasing

def is_increasing(seq):
    # Check if sequence is strictly increasing
    for i in range(len(seq) - 1):
        if seq[i] >= seq[i + 1]:
            return False
    return True

def fill_zeros(a, b, assignment):
    # Fill zeros in a with elements from b according to assignment
    result = []
    b_idx = 0
    for val in a:
        if val == 0:
            result.append(assignment[b_idx])
            b_idx += 1
        else:
            result.append(val)
    return result

def try_all_permutations(a, b):
    # Try all permutations of b and check if any makes sequence non-increasing
    from itertools import permutations
    for perm in permutations(b):
        filled = fill_zeros(a, b, perm)
        if not is_increasing(filled):
            return True
    return False

