def construct_smallest(digits, substring, n_digits):
    best = None

    for start_pos in range(n_digits - len(substring) + 1):
        available = digits[:]

        # Try to place substring
        valid = True
        for ch in substring:
            if ch in available:
                available.remove(ch)
            else:
                valid = False
                break

        if not valid:
            continue

        # Build result
        result = [None] * n_digits
        for i, ch in enumerate(substring):
            result[start_pos + i] = ch

        # Fill remaining with smallest digits
        available.sort()

        # If we need to place a digit at position 0 and it would be '0', find a non-zero first
        if result[0] is None and n_digits > 1:
            # Find first non-zero in available
            found_nonzero = False
            for i, digit in enumerate(available):
                if digit != '0':
                    result[0] = digit
                    available.pop(i)
                    found_nonzero = True
                    break
            if not found_nonzero:
                # All available digits are '0', can't proceed (leading zero not allowed)
                continue

        # Fill remaining positions in order
        for i in range(n_digits):
            if result[i] is None and available:
                result[i] = available.pop(0)

        # Check if we successfully filled all positions
        if None in result:
            continue

        # Check for leading zero (not allowed unless it's a single digit "0")
        if n_digits > 1 and result[0] == '0':
            continue

        candidate = ''.join(result)
        if substring in candidate:
            if best is None or int(candidate) < int(best):
                best = candidate

    return best

